description:
Write the accumulator of lesson 3.04 as a class, with the spiral-of-death guard and a one-off press that steps consume:

```cpp
struct Vector2 { float x, y; };

class FixedStep
{
public:
    FixedStep(float step, int maxSteps);
    int advance(float frameTime);     // how many steps to run this frame
    float alpha() const;              // accumulator / step after advance
    void press();                     // a one-off input this frame
    bool takePress();                 // true once per press, for the first step that asks
};

Vector2 lerp(Vector2 a, Vector2 b, float t);
```

- `advance` clamps the frame time to at most 0.25 s, adds it to the accumulator, and counts steps while the accumulator holds at least one step, subtracting a step each time. When `maxSteps` is reached, the accumulator is set to 0 (the game slows down rather than freezing).
- `press` sets a flag; `takePress` returns it and clears it. A press in a frame with no steps is still there for the next frame's first step.

starter.solution.cpp:
struct Vector2 { float x, y; };

class FixedStep
{
public:
    FixedStep(float step, int maxSteps) {}
    int advance(float frameTime) { return 0; }
    float alpha() const { return 0; }
    void press() {}
    bool takePress() { return false; }
};

Vector2 lerp(Vector2 a, Vector2 b, float t) { return a; }

solution.solution.cpp:
#include <algorithm>

struct Vector2 { float x, y; };

class FixedStep
{
public:
    FixedStep(float step, int maxSteps) : m_step{ step }, m_maxSteps{ maxSteps } {}

    int advance(float frameTime)
    {
        m_accumulator += std::min(frameTime, 0.25f);
        int steps{ 0 };
        while (m_accumulator >= m_step)
        {
            if (steps == m_maxSteps) { m_accumulator = 0; break; }
            m_accumulator -= m_step;
            ++steps;
        }
        return steps;
    }

    float alpha() const { return m_accumulator / m_step; }
    void press() { m_pressed = true; }
    bool takePress() { const bool p{ m_pressed }; m_pressed = false; return p; }

private:
    float m_step;
    int m_maxSteps;
    float m_accumulator{ 0 };
    bool m_pressed{ false };
};

Vector2 lerp(Vector2 a, Vector2 b, float t)
{
    return { a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t };
}

unitTests:
TEST("steps per frame") {
    FixedStep f{ 0.125f, 8 };
    CHECK_EQ(f.advance(0.0625f), 0); CHECK_NEAR(f.alpha(), 0.5, 1e-6);
    CHECK_EQ(f.advance(0.0625f), 1); CHECK_NEAR(f.alpha(), 0.0, 1e-6);
    CHECK_EQ(f.advance(0.25f), 2); CHECK_EQ(f.advance(1.0f), 2);
}
TEST("the same number of steps at any frame rate") {
    FixedStep fast{ 0.125f, 8 }, slow{ 0.125f, 8 }; int a = 0, b = 0;
    for (int i = 0; i < 64; ++i) a += fast.advance(0.03125f);
    for (int i = 0; i < 8; ++i) b += slow.advance(0.25f);
    CHECK_EQ(a, 16); CHECK_EQ(b, 16);
}
TEST("spiral guard") { FixedStep f{ 0.01f, 5 }; CHECK_EQ(f.advance(0.2f), 5); CHECK_NEAR(f.alpha(), 0.0, 1e-6); CHECK_EQ(f.advance(5.0f), 5); }
TEST("presses wait for a step") {
    FixedStep f{ 0.125f, 8 }; f.press();
    CHECK_EQ(f.advance(0.0625f), 0); CHECK_EQ(f.advance(0.0625f), 1);
    CHECK(f.takePress()); CHECK(!f.takePress());
}
TEST("interpolation") { const Vector2 p = lerp({ 0, 10 }, { 8, 20 }, 0.25f); CHECK_NEAR(p.x, 2.0, 1e-6); CHECK_NEAR(p.y, 12.5, 1e-6); }

